use std::io::Write;
use std::os::unix::ffi::OsStrExt;

/// Faithful port of glibc atoi(s) == (int)strtol(s, NULL, 10)
fn c_atoi(bytes: &[u8]) -> i32 {
    let mut i = 0usize;
    // 1. skip C isspace (C locale): ' ', \t, \n, \v, \f, \r
    while i < bytes.len()
        && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
    {
        i += 1;
    }
    // 2. optional single sign
    let mut neg = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        neg = bytes[i] == b'-';
        i += 1;
    }
    // 3. accumulate decimal digits, saturating at i64 bounds
    let mut acc: i64 = 0;
    let mut sat = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let d = (bytes[i] - b'0') as i64;
        if !sat {
            if neg {
                match acc.checked_mul(10).and_then(|v| v.checked_sub(d)) {
                    Some(v) => acc = v,
                    None => { acc = i64::MIN; sat = true; }
                }
            } else {
                match acc.checked_mul(10).and_then(|v| v.checked_add(d)) {
                    Some(v) => acc = v,
                    None => { acc = i64::MAX; sat = true; }
                }
            }
        }
        i += 1;
    }
    // 4. truncate to int
    acc as i32
}

fn main() {
    let out = std::io::stdout();
    let mut w = std::io::BufWriter::new(out.lock());
    for a in std::env::args_os().skip(1) {
        writeln!(w, "{}", c_atoi(a.as_bytes())).unwrap();
    }
}
EOF
