use std::io::Write;
fn main() {
    // xorshift PRNG, deterministic
    let mut s: u64 = 0x243F6A8885A308D3;
    let mut rnd = move || { s ^= s << 13; s ^= s >> 7; s ^= s << 17; s };
    let alpha: Vec<u8> = {
        let mut v = Vec::new();
        for _ in 0..14 { for d in b'0'..=b'9' { v.push(d); } } // digits heavy
        v.extend_from_slice(b"++--  \t\n\x0b\x0c\r");
        v.extend_from_slice(b"aAxXeE.,_zZ/:");
        v.extend_from_slice(&[0x80, 0xa0, 0xc3, 0xff, 0xfe, 0x7f, 0x01]);
        v
    };
    let out = std::io::stdout();
    let mut w = std::io::BufWriter::new(out.lock());
    for _ in 0..60000 {
        let len = (rnd() % 26) as usize; // 0..25 bytes
        let mut buf = Vec::with_capacity(len);
        for _ in 0..len {
            buf.push(alpha[(rnd() % alpha.len() as u64) as usize]);
        }
        w.write_all(&buf).unwrap();
        w.write_all(&[0u8]).unwrap();
    }
    // targeted edge cases around the i64/i32 boundaries
    let edges: Vec<String> = {
        let mut v = Vec::new();
        for base in [0i128, 2147483647, 2147483648, 4294967295, 4294967296,
                     9223372036854775807, 9223372036854775808,
                     18446744073709551615, 18446744073709551616,
                     99999999999999999999999999] {
            for d in -3i128..=3 {
                let x = base + d;
                if x >= 0 { v.push(format!("{}", x)); v.push(format!("-{}", x)); v.push(format!("+{}", x)); }
            }
        }
        for k in 1..=25 { v.push("9".repeat(k)); v.push(format!("-{}", "9".repeat(k))); }
        for k in 1..=25 { v.push(format!("{}{}", "0".repeat(k), 7)); }
        v
    };
    for e in edges { w.write_all(e.as_bytes()).unwrap(); w.write_all(&[0u8]).unwrap(); }
}
