use std::collections::HashMap;
use std::ffi::OsStr;
use std::os::unix::ffi::OsStrExt;
use std::process::Command;

fn c_atoi(bytes: &[u8]) -> i32 {
    let mut i = 0usize;
    while i < bytes.len() && matches!(bytes[i], b' '|b'\t'|b'\n'|0x0b|0x0c|b'\r') { i += 1; }
    let mut neg = false;
    if i < bytes.len() && (bytes[i]==b'+'||bytes[i]==b'-') { neg = bytes[i]==b'-'; i+=1; }
    let mut acc: i64 = 0; let mut sat = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let d = (bytes[i]-b'0') as i64;
        if !sat {
            let r = if neg { acc.checked_mul(10).and_then(|v| v.checked_sub(d)) }
                    else   { acc.checked_mul(10).and_then(|v| v.checked_add(d)) };
            match r { Some(v)=>acc=v, None=>{ acc = if neg {i64::MIN} else {i64::MAX}; sat=true; } }
        }
        i += 1;
    }
    acc as i32
}

fn main() {
    let bin = "/workspace/dataset/test18_executable";
    // reference outputs for n = 0..=64
    let mut map: HashMap<i32, Vec<u8>> = HashMap::new();
    for n in 0..=64i32 {
        let o = Command::new(bin).arg(n.to_string()).output().unwrap();
        assert!(o.status.success() && o.stderr.is_empty());
        map.insert(n, o.stdout);
    }
    let corpus = std::fs::read("/tmp/corpus").unwrap();
    let mut tested = 0usize; let mut skipped = 0usize; let mut bad = 0usize;
    let mut neg_cases = 0usize; let mut zero_cases = 0usize;
    // deterministic sampling: take every 7th candidate to bound runtime
    for (idx, cand) in corpus.split(|b| *b == 0u8).enumerate() {
        if idx % 7 != 0 { continue; }
        if cand.is_empty() && idx + 1 == corpus.len() { continue; }
        let n = c_atoi(cand);
        if n > 64 { skipped += 1; continue; }
        let want_key = if n < 0 { 0 } else { n };
        if n < 0 { neg_cases += 1; } else if n == 0 { zero_cases += 1; }
        let o = Command::new(bin).arg(OsStr::from_bytes(cand)).output().unwrap();
        let ok = o.status.success() && o.stderr.is_empty()
              && o.stdout == *map.get(&want_key).unwrap()
              && o.stdout.last() == Some(&b'\n');
        if !ok {
            bad += 1;
            if bad <= 5 { eprintln!("MISMATCH cand={:?} predicted_n={}", String::from_utf8_lossy(cand), n); }
        }
        tested += 1;
    }
    // also: no-arg case must equal n=18
    let o = Command::new(bin).output().unwrap();
    let n18 = map.get(&18).unwrap();
    println!("noarg_equals_n18={} noarg_rc={:?} noarg_stderr_len={}",
             o.stdout == *n18, o.status.code(), o.stderr.len());
    println!("tested={} skipped_large={} negative_predicted={} zero_predicted={} MISMATCHES={}",
             tested, skipped, neg_cases, zero_cases, bad);
}
EOF
